/* Read-only resource details. No persisted or embedded production snapshots. */
(function(root){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('es-EC',{maximumFractionDigits:d}):'—';
const pct=v=>Number.isFinite(v)?num(v)+'%':'—';
function bytes(v){if(!Number.isFinite(v))return '—';const labels=['B','KiB','MiB','GiB','TiB'];let n=0;while(v>=1024&&n<4){v/=1024;n++;}return num(v,1)+' '+labels[n];}
function render(d){
 const cpu=d?.cpu,mem=d?.memory,load=cpu?.load_average,cores=d?.server.cpu_count;
 const modeLabel=d?.agent_version==='demo'?'<span class="health-demo-label">DEMO · DATOS SIMULADOS</span>':'';
 const stat=(label,value,help='')=>`<div class="health-stat"><span>${label}</span><strong>${value}</strong>${help?`<small>${help}</small>`:''}</div>`;
 const pressure=['cpu','memory','io'].map((key,i)=>{const p=d?.pressure?.[key];return `<tr><td>${['CPU','Memoria','E/S'][i]}</td><td>${pct(p?.some?.avg10)}</td><td>${pct(p?.some?.avg60)}</td><td>${pct(p?.some?.avg300)}</td><td>${key==='cpu'?'—':pct(p?.full?.avg60)}</td></tr>`;}).join('');
 const disks=(d?.disks||[]).map(v=>`<tr><td><code>${esc(v.path)}</code></td><td><span class="health-tag ${v.storage_kind==='memory'?'ram':''}">${v.storage_kind==='memory'?'RAM · tmpfs':esc(v.filesystem||'Sin identificar')}</span></td><td>${bytes(v.used_bytes)} / ${bytes(v.total_bytes)}<small class="health-sub">${pct(v.used_percent)} del límite</small></td><td>${pct(v.inodes_used_percent)}</td></tr>`).join('');
 const mounts=d?.mount_checks||[];
 return `<div class="health-grid"><section class="panel health-panel"><div class="panel-top"><div><h2>Carga y planificador</h2><p>Tareas en ejecución y en espera</p></div>${modeLabel}</div><div class="health-stats">${stat('Carga · 1 / 5 / 15 min',load?load.map(v=>num(v)).join(' / '):'—')}${stat('Carga de 15 min por CPU',Number.isFinite(load?.[2])&&cores>0?num(load[2]/cores)+'×':'—','Es una relación de tareas; no es % de CPU.')}${stat('Tareas ejecutables',num(cpu?.runnable_tasks,0),'Incluye las que ya están ejecutándose.')}${stat('Tareas bloqueadas por E/S',num(cpu?.blocked_tasks,0))}${stat('Espera de E/S',pct(cpu?.iowait_percent))}${stat('CPU retenida por el hipervisor',pct(cpu?.steal_percent),'Steal: útil en máquinas virtuales.')}</div></section><section class="panel health-panel"><div class="panel-top"><div><h2>Memoria y presión</h2><p>Disponibilidad estimada por Linux</p></div></div><div class="health-stats memory-stats">${stat('RAM disponible',bytes(mem?.available_bytes),'MemAvailable: estimación sin usar swap.')}${stat('Memoria compartida / tmpfs',bytes(mem?.shmem_bytes),'Shmem incluye otros usos compartidos.')}${stat('Swap utilizada',bytes(mem?.swap_used_bytes),mem?.swap_total_bytes!==undefined?'De '+bytes(mem.swap_total_bytes):'Dato no recibido')}</div><div class="table-wrap"><table class="health-pressure"><thead><tr><th>PSI · RECURSO</th><th>10 S</th><th>60 S</th><th>300 S</th><th>TODAS · 60 S</th></tr></thead><tbody>${pressure}</tbody></table></div><p class="health-note">PSI: porcentaje de tiempo con tareas detenidas por falta de recursos. “Todas” indica que todas las tareas no ociosas estuvieron detenidas. — significa que el dato no está disponible.</p></section></div><section class="panel health-storage"><div class="panel-top"><div><h2>Almacenamiento y montajes</h2><p>Espacio, inodos y sistemas de archivos en RAM</p></div></div>${disks?`<div class="table-wrap"><table><thead><tr><th>RUTA MEDIDA</th><th>TIPO</th><th>USO / LÍMITE</th><th>INODOS USADOS</th></tr></thead><tbody>${disks}</tbody></table></div>`:'<p class="health-note">Sin medidas de almacenamiento recibidas.</p>'}${mounts.length?`<div class="mount-watch">${mounts.map(v=>`<div class="mount-check ${v.mounted===true?'ok':v.mounted===false?'missing':'unknown'}"><span>${v.mounted===true?'✓ Montado':v.mounted===false?'! Montaje ausente':'? Sin verificar'}</span><code>${esc(v.path)}</code></div>`).join('')}</div>`:'<p class="health-note">No hay puntos de montaje esperados configurados en el agente.</p>'}<p class="health-note">El límite de un tmpfs no es memoria reservada. Su uso compite con la RAM y puede usar swap; estos valores no se suman de nuevo al uso total de memoria. Los montajes se observan desde el entorno del agente.</p></section>`;
}
const api={render};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.NexoHealth=api;
})(typeof window!=='undefined'?window:globalThis);
